import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"CI releases","description":"CI tokens call ci/releases. Job progress is admin jobs.","frontmatter":{"title":"CI releases","description":"CI tokens call ci/releases. Job progress is admin jobs."},"headers":[],"relativePath":"en/api/ci.md","filePath":"en/api/ci.md","lastUpdated":1790057721000}`),a={name:`en/api/ci.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="ci-releases" tabindex="-1">CI releases <a class="header-anchor" href="#ci-releases" aria-label="Permalink to “CI releases”">​</a></h1><p>Use a project <strong>CI token</strong> against the admin plane (default <code>:8081</code>):</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th></tr></thead><tbody><tr><td>GET, POST</td><td><code>/api/v1/admin/projects/{project_ref}/ci-tokens</code></td></tr><tr><td>DELETE</td><td><code>/api/v1/admin/projects/{project_ref}/ci-tokens/{token_id}</code></td></tr><tr><td>POST</td><td><code>/api/v1/admin/projects/{project_ref}/ci/releases</code></td></tr></tbody></table><p>GitHub Actions (or any CI/CD platform): store the token as a secret, then <code>POST ci/releases</code> after the build. Job progress is <strong>not</strong> on this page: <code>GET /api/v1/admin/jobs/{job_id}</code> (admin reference).</p><div class="info custom-block"><p class="custom-block-title">Not how KiriVers itself is released</p><p>A CI token here belongs to <strong>your project&#39;s</strong> pipeline, uploading release packages to KiriVers. The build and release pipeline for KiriVers itself is documented in <a href="/en/contribute/release">Contribute → Release and Docker</a>.</p></div><p>Explorer: <a href="/en/api/reference/">API reference</a> (<code>openapi.admin.json</code>; <a href="/en/api/scalar/admin" target="_blank" rel="noopener">open Scalar</a>).</p>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};